from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import refund_shipping
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(): return Payment("p","i",Decimal("100.00"),status="captured",created_at=T0,captured_at=T0)

# partial then full
p=mk(); refund_shipping(p,Decimal("30.00"),T0); assert p.refunded_amount==Decimal("30.00") and p.status=="captured"
refund_shipping(p,Decimal("70.00"),T0); assert p.refunded_amount==Decimal("100.00") and p.status=="refunded"
print("partial/full ok")

# over refund
p=mk()
try: refund_shipping(p,Decimal("100.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-positive
for a in [Decimal("0"),Decimal("-1")]:
    try: refund_shipping(mk(),a,T0); print("FAIL")
    except BillingError as e: print("nonpos:",e.code)

# wrong state
p=mk(); p.status="authorized"
try: refund_shipping(p,Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)

# approval
try: refund_shipping(mk(),Decimal("500.01"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
p=mk(); refund_shipping(p,Decimal("500.01"),T0,approved_by="mgr"); print("approved ok")

# idempotency retry after refunded
audit.clear()
p=mk(); refund_shipping(p,Decimal("100.00"),T0,idempotency_key="k1")
assert p.status=="refunded"
r=refund_shipping(p,Decimal("100.00"),T0,idempotency_key="k1")
assert r is p and p.refunded_amount==Decimal("100.00")
print("idempotent ok, events:",len(audit.events("payment_refunded")))

# naive datetime
try: refund_shipping(mk(),Decimal("1"),datetime(2026,1,1)); print("FAIL")
except BillingError as e: print("naive:",e.code)

# float rejected
try: refund_shipping(mk(),10.0,T0); print("FAIL")
except BillingError as e: print("float:",e.code)
print("ALL EDGE CASES OK")
EOF"}

